/// <summary>
/// Data Contract class for <c>AVABPMasterDataReport</c> SSRS report
/// </summary>
/// <remarks>
/// This is the Data Contract class for the <c>AVABPMasterDataReport</c> SSRS Report.
/// </remarks>
[
    DataContractAttribute
]
    public class AVABPMasterDataReportContract
{
    CreatedTransactionId        contractCreatedTransactionId;
    RefRecId                    contractBuildingProjectRefRecId;
    KCS_KBVBuildingProjectID    contractKCS_KBVBuildingProjectID;
    SalesTableMode              contractPrintMode;
    boolean                     contractShowActivities;
    boolean                     contractShowQuotations;
    boolean                     contractShowRequests;
    boolean                     contractShowRelations;


}

